from fastapi import FastAPI, Header, Query

app = FastAPI()

@app.get('/')
def route(query_value: str = Query(..., alias='token'), header_value: str = Header(..., alias='token')):
    return None

parameters = app.openapi()['paths']['/']['get']['parameters']
assert {(param['name'], param['in']) for param in parameters} == {('token', 'query'), ('token', 'header')}

from datetime import datetime
from pydantic import BaseModel
from fastapi.encoders import jsonable_encoder

class Model(BaseModel):
    value: datetime

    class Config:
        json_encoders = {}

model = Model(value=datetime(2020, 1, 2, 3, 4, 5))
assert jsonable_encoder(model, custom_encoder={datetime: lambda value: 'custom'}) == {'value': 'custom'}
assert jsonable_encoder(model) == {'value': '2020-01-02T03:04:05'}
